package com.paytaxihub.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="Route") public class Route { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer routeId; private String routeName,startLocation,destination; @Enumerated(EnumType.STRING) private FareType fareType; private BigDecimal fareRate, estimatedDistanceKm; private Boolean isActive; public enum FareType{Per_KM,Fixed} public Route(){} public Integer getRouteId(){return routeId;} public void setRouteId(Integer v){routeId=v;} public String getRouteName(){return routeName;} public void setRouteName(String v){routeName=v;} public String getStartLocation(){return startLocation;} public void setStartLocation(String v){startLocation=v;} public String getDestination(){return destination;} public void setDestination(String v){destination=v;} public FareType getFareType(){return fareType;} public void setFareType(FareType v){fareType=v;} public BigDecimal getEstimatedDistanceKm(){return estimatedDistanceKm;} public void setEstimatedDistanceKm(BigDecimal v){estimatedDistanceKm=v;} public BigDecimal getFareRate(){return fareRate;} public void setFareRate(BigDecimal v){fareRate=v;} public Boolean getIsActive(){return isActive;} public void setIsActive(Boolean v){isActive=v;} }
